        levelEntity.setId(id);

        return levelRepository.findById(id).map(existingLevel -> {
            // Update associations if new ones (with IDs) are provided
            if (levelEntity.getCharacter() != null) {
                if (levelEntity.getCharacter().getId() != null) {
